	local function getF3X()	
	    local p = game.Players.LocalPlayer	
	    local tool = p.Backpack:FindFirstChild("Building Tools") or (p.Character and p.Character:FindFirstChild("Building Tools"))	
	    if not tool or not tool:FindFirstChild("SyncAPI") then	
